exercises.starter_code:
public class Main {
    public static void main(String[] args) {
        String text = "Hello, World!";
    }
}

exercises.solution:
public class Main {
    public static void main(String[] args) {
        String text = "Hello, World!";
        System.out.println("Contains: " + text.contains("Hello"));
        System.out.println("Replaced: " + text.replace("World", "Go"));
        System.out.println("First: " + "a,b,c".split(",")[0]);
    }
}

