    }
}

exercises.solution:
public class Main {
    public static void main(String[] args) {
        String name = "Alice";
        int age = 30;
        double pi = 3.14159;
        System.out.println(name + " is " + age + " years old");
        System.out.printf("Pi is %.2f%n", pi);
    }
}

